/* KiVitronics — Option B. Generated by build.js from src/scripts. Do not edit directly. */
/**
 * Motion core.
 *
 * One rAF loop, one read pass, one write pass. Sections register a "scrub"
 * and receive a 0→1 progress value as the CSS custom property `--p`; every
 * animation on the page is expressed against that single variable, so motion
 * stays cheap and consistent.
 */
(function () {
  'use strict';

  var reduceQuery = window.matchMedia('(prefers-reduced-motion: reduce)');

  var KV = (window.KV = {
    reduced: reduceQuery.matches,
    scrubs: [],
    /** Scrub names claimed by a module, so autoScrub doesn't double-register. */
    claimed: {},
    frameTasks: [],
    resizeTasks: [],
    clamp: function (v, min, max) {
      return v < min ? min : v > max ? max : v;
    },
    /** Deterministic pseudo-random so layouts never jump between loads. */
    rand: function (seed) {
      var x = Math.sin(seed * 127.1 + 311.7) * 43758.5453;
      return x - Math.floor(x);
    },
  });

  /* ---------- progress modes ---------- */

  var modes = {
    /* Enters from the bottom, completes as it clears the upper third. */
    enter: function (rect, vh) {
      var start = vh * 0.9;
      var span = vh * 0.5 + rect.height;
      return (start - rect.top) / span;
    },
    /* Completes within the first screen of scrolling. */
    hero: function (rect, vh) {
      return -rect.top / (vh * 0.34);
    },
    /* Runs for the length of a pinned container. */
    pin: function (rect, vh) {
      var travel = rect.height - vh;
      return travel <= 0 ? 1 : -rect.top / travel;
    },
  };

  var MODE_BY_NAME = {
    hero: 'hero',
    proof: 'enter',
    gap: 'enter',
    qual: 'enter',
    journey: 'enter',
    clients: 'enter',
    intel: 'enter',
    cta: 'enter',
  };

  /**
   * Register an element for scroll-scrubbed progress.
   * @param {Element} el
   * @param {string} mode  key of `modes`
   * @param {Function} [onUpdate] called with (p, el) after `--p` is written
   */
  KV.registerScrub = function (el, mode, onUpdate) {
    if (!el) return;
    var entry = { el: el, mode: modes[mode] || modes.enter, onUpdate: onUpdate, p: -1, visible: false };
    KV.scrubs.push(entry);

    if ('IntersectionObserver' in window) {
      new IntersectionObserver(
        function (entries) {
          entry.visible = entries[0].isIntersecting;
          if (entry.visible) schedule();
        },
        { rootMargin: '120px 0px' }
      ).observe(el);
    } else {
      entry.visible = true;
    }

    if (KV.reduced) {
      el.style.setProperty('--p', '1');
      if (onUpdate) onUpdate(1, el);
    }
    return entry;
  };

  KV.onFrame = function (fn) { KV.frameTasks.push(fn); };
  KV.onResize = function (fn) { KV.resizeTasks.push(fn); fn(); };

  /* ---------- the loop ---------- */

  var queued = false;

  function schedule() {
    if (queued) return;
    queued = true;
    requestAnimationFrame(tick);
  }

  function tick() {
    queued = false;
    if (KV.reduced) return;

    var vh = window.innerHeight;
    var i, entry, p;

    for (i = 0; i < KV.scrubs.length; i++) {
      entry = KV.scrubs[i];
      if (!entry.visible) continue;
      p = KV.clamp(entry.mode(entry.el.getBoundingClientRect(), vh), 0, 1);
      if (Math.abs(p - entry.p) < 0.0009) continue;
      entry.p = p;
      entry.el.style.setProperty('--p', p.toFixed(4));
      if (entry.onUpdate) entry.onUpdate(p, entry.el);
    }

    for (i = 0; i < KV.frameTasks.length; i++) KV.frameTasks[i]();
  }

  window.addEventListener('scroll', schedule, { passive: true });
  window.addEventListener('resize', function () {
    for (var i = 0; i < KV.resizeTasks.length; i++) KV.resizeTasks[i]();
    for (var j = 0; j < KV.scrubs.length; j++) KV.scrubs[j].p = -1;
    schedule();
  });

  reduceQuery.addEventListener('change', function (e) {
    KV.reduced = e.matches;
    if (!KV.reduced) schedule();
  });

  /* ---------- reveal ---------- */

  KV.initReveal = function (root) {
    var nodes = (root || document).querySelectorAll('[data-reveal]');
    if (KV.reduced || !('IntersectionObserver' in window)) {
      nodes.forEach(function (n) { n.classList.add('is-in'); });
      return;
    }
    var io = new IntersectionObserver(
      function (entries) {
        entries.forEach(function (e) {
          if (!e.isIntersecting) return;
          e.target.classList.add('is-in');
          io.unobserve(e.target);
        });
      },
      { rootMargin: '0px 0px -12% 0px', threshold: 0.08 }
    );
    nodes.forEach(function (n) { io.observe(n); });
  };

  /** Turn a 0→1 progress into "the first N of these are active". */
  KV.activate = function (nodes, p, count, lead) {
    var reached = p * (count + (lead || 0.6));
    for (var i = 0; i < nodes.length; i++) {
      nodes[i].classList.toggle('is-on', reached > i + 0.35);
    }
  };

  KV.autoScrub = function () {
    document.querySelectorAll('[data-scrub]').forEach(function (el) {
      var name = el.getAttribute('data-scrub');
      if (KV.claimed[name]) return;
      KV.registerScrub(el, MODE_BY_NAME[name] || 'enter');
    });
  };

  KV.MODE_BY_NAME = MODE_BY_NAME;
  KV.schedule = schedule;
})();

/** Nav: hides on the way down, inverts over dark sections, tracks position. */
(function () {
  'use strict';
  var KV = window.KV;

  KV.initNav = function () {
    var nav = document.querySelector('[data-nav]');
    var toggle = document.querySelector('[data-nav-toggle]');
    var drawer = document.querySelector('[data-drawer]');
    var rail = document.querySelector('[data-rail]');
    if (!nav) return;

    var lastY = window.scrollY;
    var navH = nav.offsetHeight;
    var darkSections = [];
    var linkMap = [];

    KV.onResize(function () {
      navH = nav.offsetHeight;
      darkSections = [].slice.call(
        document.querySelectorAll('.section--night, .model, .cta, .foot')
      );
      linkMap = [].slice.call(document.querySelectorAll('[data-nav-link]')).map(function (a) {
        return { link: a, target: document.querySelector(a.getAttribute('href')) };
      });
      positionRailTicks();
    });

    function positionRailTicks() {
      if (!rail) return;
      var docH = document.documentElement.scrollHeight;
      rail.querySelectorAll('[data-rail-tick]').forEach(function (li) {
        var target = document.getElementById(li.getAttribute('data-rail-tick'));
        if (!target) { li.style.display = 'none'; return; }
        var top = target.getBoundingClientRect().top + window.scrollY;
        li.style.setProperty('--tick-p', (top / docH).toFixed(4));
      });
    }

    KV.onFrame(function () {
      var y = window.scrollY;
      var docH = document.documentElement.scrollHeight - window.innerHeight;
      var progress = docH > 0 ? KV.clamp(y / docH, 0, 1) : 0;

      nav.style.setProperty('--scroll-p', progress.toFixed(4));
      if (rail) rail.style.setProperty('--rail-p', progress.toFixed(4));

      nav.classList.toggle('is-stuck', y > 8);

      var open = drawer && !drawer.hidden;
      nav.classList.toggle('is-hidden', !open && y > 240 && y > lastY + 4);
      if (Math.abs(y - lastY) > 3) lastY = y;

      // invert whenever the nav sits over a dark surface
      var probe = navH * 0.5;
      var inverse = darkSections.some(function (s) {
        var r = s.getBoundingClientRect();
        return r.top <= probe && r.bottom > probe;
      });
      nav.classList.toggle('is-inverse', inverse);
      if (rail) rail.classList.toggle('is-inverse', inverse);

      // current chapter
      var currentId = null;
      linkMap.forEach(function (m) {
        if (!m.target) return;
        var r = m.target.getBoundingClientRect();
        if (r.top <= window.innerHeight * 0.45 && r.bottom > window.innerHeight * 0.45) {
          currentId = m.link;
        }
      });
      linkMap.forEach(function (m) { m.link.classList.toggle('is-current', m.link === currentId); });

      if (rail) {
        var vhMid = window.innerHeight * 0.45;
        rail.querySelectorAll('[data-rail-tick]').forEach(function (li) {
          var t = document.getElementById(li.getAttribute('data-rail-tick'));
          if (!t) return;
          var r = t.getBoundingClientRect();
          li.classList.toggle('is-active', r.top <= vhMid && r.bottom > vhMid);
        });
      }
    });

    /* ---------- drawer ---------- */
    if (toggle && drawer) {
      var setOpen = function (open) {
        toggle.setAttribute('aria-expanded', String(open));
        drawer.hidden = !open;
        document.body.style.overflow = open ? 'hidden' : '';
        if (open) {
          nav.classList.remove('is-hidden');
          var first = drawer.querySelector('a');
          if (first) first.focus({ preventScroll: true });
        }
      };
      toggle.addEventListener('click', function () {
        setOpen(toggle.getAttribute('aria-expanded') !== 'true');
      });
      drawer.querySelectorAll('[data-drawer-link]').forEach(function (a) {
        a.addEventListener('click', function () { setOpen(false); });
      });
      document.addEventListener('keydown', function (e) {
        if (e.key === 'Escape' && !drawer.hidden) { setOpen(false); toggle.focus(); }
      });
    }
  };
})();

/**
 * HERO — convergence.
 * Tiles scatter across the field, drift, then travel to a single stack against
 * the open mandate as the hero scrolls. Positions are computed from the field
 * box so the composition holds at any size.
 */
(function () {
  'use strict';
  var KV = window.KV;

  KV.initHero = function () {
    var hero = document.querySelector('[data-scrub="hero"]');
    var field = document.querySelector('[data-hero-field]');
    var slot = document.querySelector('[data-hero-slot]');
    if (!hero || !field || !slot) return;

    var tiles = [].slice.call(field.querySelectorAll('[data-hero-tile]'));
    var compact = window.matchMedia('(max-width: 899px)');
    KV.claimed.hero = true;

    function layout() {
      var fr = field.getBoundingClientRect();
      var sr = slot.getBoundingClientRect();
      if (!fr.width) return;

      // Must match the CSS breakpoint that moves the slot, or the two
      // layouts disagree about where the mandate is.
      var narrow = compact.matches;
      // Everything scatters to the left of the mandate; nothing overlaps it.
      var slotLeft = sr.left - fr.left;
      var zoneW = narrow ? fr.width : Math.max(slotLeft - 28, fr.width * 0.42);
      var zoneH = narrow ? Math.max(fr.height - sr.height - 26, 120) : fr.height;

      var targetX = narrow ? fr.width / 2 - 44 : Math.max(slotLeft - 56, 0);
      var targetY = narrow ? zoneH - 18 : fr.height / 2;

      tiles.forEach(function (tile, i) {
        var w = tile.offsetWidth || 76;
        var h = tile.offsetHeight || 26;
        var rx = KV.rand(i + 1);
        var ry = KV.rand(i + 41);

        // Each tile owns one cell and jitters inside it: never a visible grid,
        // never two labels on top of each other.
        var cols = 3;
        var rows = Math.ceil(tiles.length / cols);
        var col = i % cols;
        var row = Math.floor(i / cols);
        var cellW = zoneW / cols;
        var cellH = zoneH / rows;
        var x = col * cellW + rx * Math.max(cellW - w, 0);
        var y = row * cellH + ry * Math.max(cellH - h, 0);

        tile.style.setProperty('--sx', x.toFixed(1) + 'px');
        tile.style.setProperty('--sy', y.toFixed(1) + 'px');
        tile.style.setProperty('--dx', (targetX - x).toFixed(1) + 'px');
        tile.style.setProperty('--dy', (targetY + (i - tiles.length / 2) * 4.5 - y).toFixed(1) + 'px');
        tile.style.zIndex = String(tiles.length - i);
      });
    }

    KV.onResize(layout);
    compact.addEventListener('change', layout);
    // Fonts change tile widths; re-measure once they land.
    if (document.fonts && document.fonts.ready) document.fonts.ready.then(layout);

    KV.registerScrub(hero, 'hero', function (p) {
      var matched = p > 0.82;
      slot.classList.toggle('is-filled', matched);
      tiles.forEach(function (tile, i) {
        tile.classList.toggle('is-matched', matched && i === 0);
        tile.classList.toggle('is-dim', matched && i !== 0);
      });
    });
  };
})();

/**
 * THE GAP — leakage.
 * Units travel the track and leave it at the stage where hiring typically
 * loses them. The distribution is illustrative: it is deliberately NOT one of
 * the KiVitronics metrics, and nothing in this section is labelled as one.
 */
(function () {
  'use strict';
  var KV = window.KV;

  // stop position along the track (0–1); 1 means the unit reaches day one
  var EXITS = [0.29, 0.29, 0.29, 0.55, 0.55, 0.55, 0.8, 0.8, 1, 1, 1, 1];
  var LANES = [-21, -7, 7, 21];

  KV.initGap = function () {
    var section = document.querySelector('[data-scrub="gap"]');
    var figure = document.querySelector('[data-gap]');
    if (!section || !figure) return;
    KV.claimed.gap = true;

    var units = [].slice.call(figure.querySelectorAll('[data-gap-unit]'));
    var stages = [].slice.call(figure.querySelectorAll('[data-gap-stage]'));
    var track = figure.querySelector('.gap__track');

    units.forEach(function (u, i) {
      var stop = EXITS[i % EXITS.length];
      u.style.setProperty('--stop', String(stop));
      u.style.setProperty('--lane', LANES[i % LANES.length] + 'px');
      if (stop >= 1) u.classList.add('is-survivor');
    });

    KV.onResize(function () {
      var w = (track ? track.clientWidth : figure.clientWidth) - 12;
      units.forEach(function (u) { u.style.setProperty('--span', Math.max(w, 80) + 'px'); });
    });

    KV.registerScrub(section, 'enter', function (p) {
      KV.activate(stages, p, stages.length, 0.2);
    });
  };
})();

/**
 * THE MODEL — nine stages.
 * Wide screens pin the section and pull the track sideways, so the page's
 * vertical scroll literally moves a unit through the journey. Narrow screens
 * get the same nine beats as a vertical track that lights up in sequence.
 */
(function () {
  'use strict';
  var KV = window.KV;

  KV.initModel = function () {
    var section = document.querySelector('[data-model]');
    if (!section) return;

    var track = section.querySelector('[data-model-track]');
    var viewport = section.querySelector('.model__viewport');
    var stages = [].slice.call(section.querySelectorAll('[data-model-stage]'));
    var counter = section.querySelector('[data-model-count]');
    var unit = section.querySelector('[data-model-unit]');
    var wide = window.matchMedia('(min-width: 900px)');

    KV.onResize(function () {
      if (!track || !viewport) return;
      var shift = wide.matches ? Math.max(track.scrollWidth - viewport.clientWidth, 0) : 0;
      section.style.setProperty('--shift', shift + 'px');
    });

    function update(p) {
      var current = 0;

      if (KV.reduced) {
        // Every stage reads at once; nothing is singled out as "now".
        stages.forEach(function (s) { s.classList.add('is-on'); s.classList.remove('is-current'); });
        if (counter) counter.textContent = ('0' + stages.length).slice(-2);
        return;
      }

      if (wide.matches && viewport) {
        // The stage sitting at the playhead is the one being worked, and
        // everything it has already passed stays lit behind it.
        var playX = viewport.getBoundingClientRect().left + 10;
        stages.forEach(function (stage, i) {
          var r = stage.getBoundingClientRect();
          var passed = r.left <= playX;
          stage.classList.toggle('is-on', passed);
          stage.classList.toggle('is-current', passed && r.right > playX);
          if (passed) current = i + 1;
        });
      } else {
        KV.activate(stages, p, stages.length, 0.6);
        current = stages.filter(function (s) { return s.classList.contains('is-on'); }).length;
        stages.forEach(function (s, i) { s.classList.toggle('is-current', i === current - 1); });
      }

      var index = KV.clamp(current || 1, 1, stages.length);
      if (counter) counter.textContent = ('0' + index).slice(-2);
      if (unit) unit.classList.toggle('is-joined', index === stages.length);
    }

    // The pinned container is the scrub on wide screens; the section itself
    // otherwise, so the same code drives both interpretations.
    KV.registerScrub(section, wide.matches ? 'pin' : 'enter', function (p) { update(p); });

    wide.addEventListener('change', function () {
      KV.scrubs.forEach(function (s) {
        if (s.el === section) s.mode = wide.matches ? modePin : modeEnter;
      });
      window.dispatchEvent(new Event('resize'));
    });

    // captured here so the media-query swap can reuse them
    var modePin = function (rect, vh) {
      var travel = rect.height - vh;
      return travel <= 0 ? 1 : -rect.top / travel;
    };
    var modeEnter = function (rect, vh) {
      return (vh * 0.9 - rect.top) / (vh * 0.5 + rect.height);
    };
  };
})();

/** Qualification, candidate journey and the closing track. */
(function () {
  'use strict';
  var KV = window.KV;

  KV.initSequences = function () {
    /* ---------- qualification: five assays in sequence ---------- */
    var qual = document.querySelector('[data-scrub="qual"]');
    if (qual) {
      KV.claimed.qual = true;
      var rows = [].slice.call(qual.querySelectorAll('[data-qual-row]'));
      var profile = qual.querySelector('[data-qual-profile]');
      KV.onResize(function () {
        rows.forEach(function (row) {
          var rail = row.querySelector('.qual__assay');
          if (rail) row.style.setProperty('--assay-w', Math.max(rail.clientWidth - 7, 0) + 'px');
        });
      });
      KV.registerScrub(qual, 'enter', function (p) {
        KV.activate(rows, p, rows.length, 0.9);
        if (profile) profile.classList.toggle('is-complete', p > 0.86);
      });
    }

    /* ---------- candidate journey: one unbroken line ---------- */
    var journey = document.querySelector('[data-scrub="journey"]');
    if (journey) {
      KV.claimed.journey = true;
      var steps = [].slice.call(journey.querySelectorAll('[data-journey-step]'));
      KV.registerScrub(journey, 'enter', function (p) {
        KV.activate(steps, p, steps.length, 0.9);
      });
    }

    /* ---------- closing track: the unit arrives ---------- */
    var cta = document.querySelector('[data-scrub="cta"]');
    if (cta) {
      KV.claimed.cta = true;
      var terminal = cta.querySelector('[data-cta-terminal]');
      var tile = cta.querySelector('[data-cta-tile]');
      var node = terminal && terminal.querySelector('.cta__node');
      KV.onResize(function () {
        if (!terminal || !node) return;
        var span = terminal.clientWidth - node.offsetWidth - 16;
        terminal.style.setProperty('--span', Math.max(span, 40) + 'px');
      });
      KV.registerScrub(cta, 'enter', function (p) {
        var joined = p > 0.9;
        if (tile) tile.classList.toggle('is-joined', joined);
        if (terminal) terminal.classList.toggle('is-joined', joined);
      });
    }
  };
})();

/** Numbers count once on entry, then stop. No looping. */
(function () {
  'use strict';
  var KV = window.KV;

  var easeOut = function (t) { return 1 - Math.pow(1 - t, 3); };

  KV.initCounters = function () {
    var nodes = [].slice.call(document.querySelectorAll('[data-count]'));
    if (!nodes.length) return;

    if (KV.reduced || !('IntersectionObserver' in window)) {
      nodes.forEach(function (n) { n.textContent = n.getAttribute('data-count'); });
      return;
    }

    var io = new IntersectionObserver(
      function (entries) {
        entries.forEach(function (e) {
          if (!e.isIntersecting) return;
          io.unobserve(e.target);
          run(e.target);
        });
      },
      { threshold: 0.5 }
    );
    nodes.forEach(function (n) { io.observe(n); });

    function run(node) {
      var target = parseFloat(node.getAttribute('data-count')) || 0;
      var duration = 1150;
      var start = 0;
      function step(now) {
        if (!start) start = now;
        var t = KV.clamp((now - start) / duration, 0, 1);
        node.textContent = String(Math.round(easeOut(t) * target));
        if (t < 1) requestAnimationFrame(step);
      }
      requestAnimationFrame(step);
    }
  };

  /** Client field: 25 marks, 15 of them repeat clients. */
  KV.initClientField = function () {
    var field = document.querySelector('[data-clients-field]');
    if (!field) return;
    if (KV.reduced || !('IntersectionObserver' in window)) { field.classList.add('is-in'); return; }
    var io = new IntersectionObserver(
      function (entries) {
        if (!entries[0].isIntersecting) return;
        field.classList.add('is-in');
        io.disconnect();
      },
      { threshold: 0.25 }
    );
    io.observe(field);
  };
})();

/** Solutions index and the FAQ tabs + accordion. */
(function () {
  'use strict';
  var KV = window.KV;

  /* Each solution lights a different configuration of the same 16 cells:
     one engine, five arrangements. */
  var FIELDS = [
    [0, 1, 4, 5, 8, 9, 10, 13],
    [0, 1, 2, 3, 4, 7, 8, 11, 12, 13, 14, 15],
    [5, 6, 9, 10],
    [0, 3, 5, 6, 9, 10, 12, 15],
    [0, 1, 2, 3, 12, 13, 14, 15],
  ];

  KV.initSolutions = function () {
    var list = document.querySelector('[data-sol]');
    if (!list) return;
    var triggers = [].slice.call(list.querySelectorAll('[data-sol-trigger]'));
    var panels = [].slice.call(list.querySelectorAll('[data-sol-panel]'));
    var cells = [].slice.call(document.querySelectorAll('[data-sol-field] .sol__cell'));

    function paint(index) {
      var lit = FIELDS[index % FIELDS.length];
      cells.forEach(function (cell, i) {
        cell.classList.toggle('is-lit', lit.indexOf(i) !== -1);
        cell.classList.toggle('is-half', lit.indexOf(i) === -1 && (i + index) % 3 === 0);
      });
    }

    function open(index) {
      triggers.forEach(function (t, i) { t.setAttribute('aria-expanded', String(i === index)); });
      panels.forEach(function (p, i) {
        if (i === index) p.setAttribute('data-open', '');
        else p.removeAttribute('data-open');
      });
      paint(index);
    }

    triggers.forEach(function (t, i) {
      t.addEventListener('click', function () {
        open(t.getAttribute('aria-expanded') === 'true' ? -1 : i);
      });
      // Hovering previews the configuration without changing the open row.
      t.addEventListener('mouseenter', function () { if (!KV.reduced) paint(i); });
    });
    list.addEventListener('mouseleave', function () {
      var current = triggers.findIndex(function (t) { return t.getAttribute('aria-expanded') === 'true'; });
      if (current > -1) paint(current);
    });

    open(0);
  };

  KV.initFaq = function () {
    var root = document.querySelector('[data-faq]');
    if (!root) return;

    var tabs = [].slice.call(root.querySelectorAll('[data-faq-tab]'));
    var panels = [].slice.call(root.querySelectorAll('[data-faq-panel]'));
    var mark = root.querySelector('[data-faq-mark]');

    function moveMark(tab) {
      if (!mark || !tab) return;
      mark.style.setProperty('--mark-w', tab.offsetWidth + 'px');
      mark.style.setProperty('--mark-x', tab.offsetLeft + 'px');
    }

    function select(index, focus) {
      tabs.forEach(function (t, i) {
        t.setAttribute('aria-selected', String(i === index));
        t.tabIndex = i === index ? 0 : -1;
        if (i === index && focus) t.focus();
      });
      panels.forEach(function (p, i) { p.hidden = i !== index; });
      moveMark(tabs[index]);
    }

    tabs.forEach(function (t, i) {
      t.addEventListener('click', function () { select(i); });
      t.addEventListener('keydown', function (e) {
        var next = e.key === 'ArrowRight' ? i + 1 : e.key === 'ArrowLeft' ? i - 1
          : e.key === 'Home' ? 0 : e.key === 'End' ? tabs.length - 1 : null;
        if (next === null) return;
        e.preventDefault();
        select((next + tabs.length) % tabs.length, true);
      });
    });

    // Accordion: one answer open at a time, per panel.
    root.querySelectorAll('[data-faq-q]').forEach(function (q) {
      q.addEventListener('click', function () {
        var isOpen = q.getAttribute('aria-expanded') === 'true';
        var panel = q.closest('[data-faq-panel]');
        panel.querySelectorAll('[data-faq-q]').forEach(function (other) {
          other.setAttribute('aria-expanded', 'false');
          var a = document.getElementById(other.getAttribute('aria-controls'));
          if (a) a.removeAttribute('data-open');
        });
        if (!isOpen) {
          q.setAttribute('aria-expanded', 'true');
          var answer = document.getElementById(q.getAttribute('aria-controls'));
          if (answer) answer.setAttribute('data-open', '');
        }
      });
    });

    KV.onResize(function () {
      var active = tabs.find(function (t) { return t.getAttribute('aria-selected') === 'true'; });
      moveMark(active || tabs[0]);
    });
    if (document.fonts && document.fonts.ready) {
      document.fonts.ready.then(function () { moveMark(tabs[0]); });
    }
  };
})();

/**
 * Contact form.
 * Validation is real. Submission is not faked: with no verified endpoint
 * configured, the form says so plainly rather than pretending to send.
 */
(function () {
  'use strict';
  var KV = window.KV;

  KV.initForm = function () {
    var form = document.querySelector('[data-form]');
    if (!form) return;
    var status = form.querySelector('[data-form-status]');
    var hasEndpoint = Boolean(form.getAttribute('action'));

    form.addEventListener('submit', function (e) {
      var invalid = null;
      [].slice.call(form.querySelectorAll('input, textarea')).forEach(function (field) {
        var ok = field.checkValidity();
        field.setAttribute('aria-invalid', ok ? 'false' : 'true');
        if (!ok && !invalid) invalid = field;
      });

      if (invalid) {
        e.preventDefault();
        invalid.focus();
        if (status) status.textContent = 'Check the highlighted fields.';
        return;
      }

      if (!hasEndpoint) {
        e.preventDefault();
        if (status) {
          status.textContent = 'Not wired up yet — add a verified endpoint before launch.';
        }
      }
    });

    form.addEventListener('input', function (e) {
      if (e.target.getAttribute('aria-invalid') === 'true' && e.target.checkValidity()) {
        e.target.setAttribute('aria-invalid', 'false');
      }
    });
  };
})();

(function () {
  'use strict';
  var KV = window.KV;

  function boot() {
    KV.initHero();
    KV.initGap();
    KV.initModel();
    KV.initSequences();
    KV.autoScrub();
    KV.initNav();
    KV.initCounters();
    KV.initClientField();
    KV.initSolutions();
    KV.initFaq();
    KV.initForm();
    KV.initReveal();
    KV.schedule();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot);
  } else {
    boot();
  }
})();
